INSERT INTO sys_config (config_key, config_value) VALUES
  ('workflows', '{"TA":[{"key":"MENTOR_SUBMIT","label":"导师提交申请","role":"MENTOR"},{"key":"DEPT_REVIEW","label":"院系名额与经费初审","role":"DEPT_ADMIN"},{"key":"INTL_REVIEW","label":"国际生办专项会签","role":"INTL_OFFICER","conditional":"allowInternational"},{"key":"PUBLISHED","label":"正式发布上线","role":"SYSTEM"}],"RA":[{"key":"MENTOR_SUBMIT","label":"导师提交申请","role":"MENTOR"},{"key":"DEPT_REVIEW","label":"院系名额与课题审核","role":"DEPT_ADMIN"},{"key":"PUBLISHED","label":"正式发布上线","role":"SYSTEM"}],"GA":[{"key":"MENTOR_SUBMIT","label":"行政科室申报","role":"MENTOR"},{"key":"DEPT_REVIEW","label":"部门初审","role":"DEPT_ADMIN"},{"key":"SCHOOL_REVIEW","label":"校级专项经费终审","role":"SCHOOL_ADMIN"},{"key":"PUBLISHED","label":"正式发布上线","role":"SYSTEM"}]}'),
  ('evaluationTemplates', '{"TA":[{"key":"mentor","label":"主讲导师教学履职评价","weight":70},{"key":"service","label":"授课学生课程评教联动","weight":30}],"RA":[{"key":"mentor","label":"课题导师科研产出评价","weight":75},{"key":"service","label":"里程碑交付与团队协作评价","weight":25}],"GA":[{"key":"mentor","label":"科室负责人值班考核","weight":60},{"key":"service","label":"服务师生满意度评价","weight":40}]}'),
