  ('jobTypeSchemas', '{"TA":{"label":"助教（TA）","desc":"绑定课程号、语言要求与教学周排班","allowedFundSources":["TA_FUND"],"defaults":{"hourlyRate":45,"weeklyHours":8,"weeks":16,"allowInternational":true},"intlToggle":{"label":"面向国际生开放（勾选后自动触发国际生办专项会签）","hint":"国际生申请人将自动校验 X1 有效学习居留许可、语言证明与 20h 周工时上限"},"fields":[{"key":"courseCode","label":"绑定课程编号","type":"text","required":true,"placeholder":"如 CS3090","defaultValue":"CS3066"},{"key":"semester","label":"授课学期","type":"text","required":true,"placeholder":"如 2026-2027 春季学期","defaultValue":"2026-2027 春季学期"},{"key":"courseName","label":"课程名称","type":"text","required":true,"placeholder":"如 操作系统原理（双语）","defaultValue":"计算机体系结构（双语）"},{"key":"minLangScore","label":"语言能力最低要求","type":"select","required":false,"defaultValue":6.5,"options":[{"value":0,"label":"无特殊语言限制"},{"value":6,"label":"IELTS 6.0 / HSK 5"},{"value":6.5,"label":"IELTS 6.5 / CET-6 550+"},{"value":7,"label":"IELTS 7.0 / TOEFL 95+"},{"value":7.5,"label":"IELTS 7.5 / TOEFL 105+"}]},{"key":"scheduleText","label":"教学周排班安排","type":"text","required":false,"placeholder":"如 周二 14:00-16:00 上机实验；周四 10:00-12:00 答疑","defaultValue":"周二 14:00-16:00 实验辅导；周四 10:00-12:00 答疑"}]},"RA":{"label":"助研（RA）","desc":"绑定科研项目、课题经费与里程碑","allowedFundSources":["RA_PROJECT"],"defaults":{"hourlyRate":48,"weeklyHours":10,"weeks":16,"allowInternational":false},"intlToggle":{"label":"允许国际研究生申请该科研助研岗位","hint":"仍将强制执行国际生签证与 20h 累计工时校验"},"fields":[{"key":"projectCode","label":"绑定科研项目编号","type":"text","required":true,"placeholder":"如 NSFC-62601234","defaultValue":"NSFC-62572018"},{"key":"researchDirection","label":"研究方向","type":"text","required":true,"placeholder":"如 多模态推理与系统优化","defaultValue":"AI 系统与高性能计算"},{"key":"projectName","label":"课题名称","type":"text","required":true,"placeholder":"","defaultValue":"面向异构集群的大模型低延迟推理优化"},{"key":"milestonesText","label":"阶段性里程碑（Milestone，每行一条）","type":"textarea","required":false,"placeholder":"每行一条，截止日期按聘期自动均分","defaultValue":"M1：完成异构算子基准测试报告\\nM2：实现多卡通信重叠优化原型\\nM3：完成实验验证与论文图表整理"}]},"GA":{"label":"助管（GA）","desc":"绑定行政科室、值班时段与专项经费","allowedFundSources":["GA_FUND"],"defaults":{"hourlyRate":35,"weeklyHours":6,"weeks":16,"allowInternational":false},"intlToggle":null,"fields":[{"key":"officeDept","label":"绑定行政科室","type":"text","required":true,"placeholder":"如 研究生院培养办","defaultValue":"研究生院综合服务大厅"},{"key":"location","label":"办公地点","type":"text","required":true,"placeholder":"如 行政楼 B306","defaultValue":"行政楼 A204"},{"key":"dutyShift","label":"值班时段","type":"text","required":true,"placeholder":"如 周二/周四 14:00-17:00","defaultValue":"周二、周四 14:00-17:00"},{"key":"fundNote","label":"专项经费说明","type":"text","required":false,"placeholder":"","defaultValue":"校级勤工助学专项经费保障"}]}}');
INSERT INTO jobs (id, type, title, dept_id, mentor_id, budget_id, quota, hired_count, hourly_rate, weekly_hours, weeks, allow_international, status, workflow_instance_id, workflow_steps, current_step_index, deadline, created_at, skills, description, extra_fields, reserved_amount) VALUES
  ('JOB_01', 'TA', '《机器学习导论（双语）》课程助教', 'DEPT_CS', 'U_MENTOR', 'B_CS_TA', 3, 1, 45, 8, 16, 1, 'PUBLISHED', 'WF_JOB_01', '["MENTOR_SUBMIT","DEPT_REVIEW","INTL_REVIEW","PUBLISHED"]', 3, '2026-12-10', '2026-10-12 09:30:00', '["Python","机器学习","英语授课"]', '协助主讲教师组织双语实验课、批改算法编程作业、每周提供2次课后答疑并维护课程评测平台。', '{"courseCode":"CS3042","courseName":"机器学习导论（双语）","semester":"2026-2027 秋季学期","languageRequirement":"IELTS 6.5 或同等水平","minLangScore":6.5,"scheduleText":"周二 14:00-16:00 实验课；周四 10:00-12:00 习题答疑","scheduleSlots":[{"day":"周二","time":"14:00-16:00","room":"计算中心 302","task":"双语实验指导"},{"day":"周四","time":"10:00-12:00","room":"明理楼 B108","task":"习题课与作业答疑"}]}', 4522.57),
  ('JOB_02', 'TA', '《高级算法与数据结构（全英文）》首席助教', 'DEPT_CS', 'U_MENTOR', 'B_CS_TA', 2, 0, 52, 12, 16, 1, 'PUBLISHED', 'WF_JOB_02', '["MENTOR_SUBMIT","DEPT_REVIEW","INTL_REVIEW","PUBLISHED"]', 3, '2026-12-15', '2026-10-18 14:15:00', '["算法","C++","英语授课"]', '面向国际本科班全英文授课辅助，负责核心算法实验设计、OJ 题库维护及期中期末阅卷协调。', '{"courseCode":"CS4018","courseName":"高级算法与数据结构（全英文）","semester":"2026-2027 秋季学期","languageRequirement":"IELTS 7.0 及以上","minLangScore":7,"scheduleText":"周一/周三 16:00-18:00 全英文习题课；周五线上答疑","scheduleSlots":[{"day":"周一","time":"16:00-18:00","room":"逸夫楼 405","task":"全英文算法研讨"},{"day":"周三","time":"16:00-18:00","room":"计算中心 201","task":"上机实验辅导"}]}', 5226.09),
  ('JOB_03', 'TA', '《国际顶会学术写作工作坊》助教', 'DEPT_CS', 'U_MENTOR', 'B_CS_TA', 1, 0, 55, 6, 12, 1, 'PUBLISHED', 'WF_JOB_03', '["MENTOR_SUBMIT","DEPT_REVIEW","INTL_REVIEW","PUBLISHED"]', 3, '2026-12-18', '2026-10-22 10:00:00', '["英语授课","学术写作","机器学习"]', '负责研究生英文论文润色辅导与 LaTeX 排版指导，需具备高水平英语读写与表达能力。', '{"courseCode":"CS6009","courseName":"国际学术论文写作工作坊","semester":"2026-2027 秋季学期","languageRequirement":"IELTS 7.5 或 TOEFL 105+","minLangScore":7.5,"scheduleText":"周四 18:30-20:30 论文写作研讨","scheduleSlots":[{"day":"周四","time":"18:30-20:30","room":"信息楼 510","task":"英文论文 Peer Review 指导"}]}', 1036.42),
  ('JOB_04', 'RA', '大模型分布式推理引擎科研助研', 'DEPT_CS', 'U_MENTOR', 'B_CS_RA', 2, 1, 48, 12, 18, 0, 'PUBLISHED', 'WF_JOB_04', '["MENTOR_SUBMIT","DEPT_REVIEW","PUBLISHED"]', 2, '2026-12-20', '2026-09-05 11:20:00', '["C++","分布式系统","Python"]', '参与国家自然科学基金重点课题，开展多卡推理调度与 KV-Cache 内存优化原型开发及基准评测。', '{"projectCode":"NSFC-62572018","projectName":"面向异构集群的大模型低延迟推理优化","researchDirection":"AI 系统架构与分布式推理","milestones":[{"id":"MS_01","title":"M1：基线推理吞吐与显存瓶颈分析报告","dueDate":"2026-10-25","done":true},{"id":"MS_02","title":"M2：动态 KV-Cache 压缩算子原型实现","dueDate":"2026-11-30","done":false},{"id":"MS_03","title":"M3：千亿参数集群评测与顶会投稿实验","dueDate":"2027-01-10","done":false}]}', 11269.07),
  ('JOB_05', 'GA', '研究生院综合服务大厅行政助管', 'DEPT_OFFICE', 'U_SCHOOL_ADMIN', 'B_GA_SCHOOL', 3, 1, 35, 6, 16, 0, 'PUBLISHED', 'WF_JOB_05', '["MENTOR_SUBMIT","DEPT_REVIEW","SCHOOL_REVIEW","PUBLISHED"]', 3, '2026-12-12', '2026-10-08 09:00:00', '["办公自动化","沟通协调"]', '协助研究生院教务窗口处理学籍证明打印、培养方案咨询引导、档案电子化归档与会议保障。', '{"officeDept":"研究生院综合服务大厅","dutyShift":"周一、周三 14:00-17:00（两班轮值）","location":"行政楼 A204","fundNote":"校级勤工助学专项经费保障"}', 10080),
  ('JOB_06', 'TA', '《人工智能伦理与治理（国际班）》助教', 'DEPT_CS', 'U_MENTOR', 'B_CS_TA', 2, 0, 45, 8, 16, 1, 'PENDING_DEPT_REVIEW', 'WF_JOB_06', '["MENTOR_SUBMIT","DEPT_REVIEW","INTL_REVIEW","PUBLISHED"]', 1, '2026-12-25', '2026-11-18 16:40:00', '["英语授课","人工智能"]', '协助全英文前沿研讨课组织案例辩论、维护中外学生小组课题进度与课堂考勤记录。', '{"courseCode":"CS5031","courseName":"人工智能伦理与治理（国际班）","semester":"2026-2027 春季预招","languageRequirement":"IELTS 6.5 及以上","minLangScore":6.5,"scheduleText":"周三 14:00-16:00 研讨课","scheduleSlots":[{"day":"周三","time":"14:00-16:00","room":"明理楼 C202","task":"国际班案例研讨组织"}]}', 3015.05),
  ('JOB_07', 'TA', '《深度学习实践（英文）》实验助教', 'DEPT_CS', 'U_MENTOR', 'B_CS_TA', 2, 0, 48, 8, 16, 1, 'PENDING_INTL_REVIEW', 'WF_JOB_07', '["MENTOR_SUBMIT","DEPT_REVIEW","INTL_REVIEW","PUBLISHED"]', 2, '2026-12-22', '2026-11-16 11:10:00', '["PyTorch","Python","英语授课"]', '负责深度学习 GPU 实验环境配置、英文实验手册编写与课程大作业答辩组织。', '{"courseCode":"CS4088","courseName":"深度学习实践（英文）","semester":"2026-2027 春季预招","languageRequirement":"IELTS 6.5 及以上","minLangScore":6.5,"scheduleText":"周五 13:30-16:30 GPU 实验室辅导","scheduleSlots":[{"day":"周五","time":"13:30-16:30","room":"智算实验楼 104","task":"PyTorch 实验上机指导"}]}', 3216.05),
  ('JOB_08', 'TA', '《高等微积分（全英文荣誉班）》助教', 'DEPT_MATH', 'U_MENTOR_MATH', 'B_MATH_TA', 2, 1, 44, 10, 16, 1, 'PUBLISHED', 'WF_JOB_08', '["MENTOR_SUBMIT","DEPT_REVIEW","INTL_REVIEW","PUBLISHED"]', 3, '2026-12-14', '2026-10-03 15:00:00', '["微积分","英语授课","LaTeX"]', '数学科学学院国际荣誉班公共基础课助教，负责习题课讲解与每周作业批改。', '{"courseCode":"MATH1012","courseName":"高等微积分（英文荣誉班）","semester":"2026-2027 秋季学期","languageRequirement":"IELTS 6.5 及以上","minLangScore":6.5,"scheduleText":"周二/周四 08:00-10:00 习题辅导","scheduleSlots":[{"day":"周二","time":"08:00-10:00","room":"理科楼 203","task":"微积分英文习题课"}]}', 3600),
  ('JOB_09', 'RA', '数字经济面板数据计量建模助研', 'DEPT_ECON', 'U_MENTOR_ECON', 'B_ECON_RA', 2, 0, 42, 8, 16, 0, 'PUBLISHED', 'WF_JOB_09', '["MENTOR_SUBMIT","DEPT_REVIEW","PUBLISHED"]', 2, '2026-12-19', '2026-10-25 10:30:00', '["Python","计量经济","数据清洗"]', '经济管理学院交叉课题，负责宏观高频数据清洗、面板回归验证及政策报告图表整理。', '{"projectCode":"KY-2026-EC02","projectName":"区域数字要素流动测度研究","researchDirection":"数字经济与计量建模","milestones":[{"id":"MS_E1","title":"M1：多源统计面板数据清洗入库","dueDate":"2026-12-05","done":false},{"id":"MS_E2","title":"M2：空间计量模型稳健性检验","dueDate":"2027-01-15","done":false}]}', 7200),
  ('JOB_10', 'RA', '跨语言多模态知识图谱构建助研', 'DEPT_CS', 'U_MENTOR', 'B_CS_RA', 2, 1, 46, 10, 16, 1, 'PUBLISHED', 'WF_JOB_10', '["MENTOR_SUBMIT","DEPT_REVIEW","PUBLISHED"]', 2, '2026-12-01', '2026-08-25 09:00:00', '["Python","PyTorch","人工智能"]', '面向中英多语种学术语料进行实体对齐与知识图谱推理实验，撰写技术文档。', '{"projectCode":"NSFC-62572018","projectName":"跨语言知识图谱与大模型对齐","researchDirection":"自然语言处理与知识工程","milestones":[{"id":"MS_K1","title":"M1：双语语料清洗与标注规范制定","dueDate":"2026-10-15","done":true},{"id":"MS_K2","title":"M2：跨语言实体对齐基准评测完成","dueDate":"2026-11-28","done":false}]}', 8138.93),
