  ('APP_05', 'JOB_02', 'U_STU_SU', 'SUBMITTED', '2026-11-17 16:05:00', '熟悉高级算法与 OJ 系统开发，申请协助全英文算法班课程辅导。', '苏雨桐_博士简历.pdf', '{"passed":true,"checks":[{"key":"lang","label":"语言能力证明校验","passed":true,"detail":"TOEFL 104 满足要求"},{"key":"hours","label":"跨岗累计工时校验","passed":true,"detail":"当前 8h + 本岗 12h = 20h ≤ 20h"}]}', 0, '', NULL, NULL, NULL, ''),
  ('APP_06', 'JOB_08', 'U_STU_ELENA', 'PENDING_SPECIAL_APPROVAL', '2026-11-18 11:25:00', 'Applied for English Honors Calculus TA; native European academic background in applied mathematics.', 'Elena_Rossi_Math_CV.pdf', '{"passed":false,"checks":[{"key":"visa","label":"国际生签证类型校验","passed":true,"detail":"X1学习居留许可有效（至 2027-06-30）"},{"key":"lang","label":"语言能力证明校验","passed":false,"detail":"已认证 IELTS 6.0，低于岗位要求 IELTS 6.5"},{"key":"hours","label":"跨岗累计工时校验","passed":true,"detail":"当前 8h + 本岗 10h = 18h ≤ 20h（临近上限）"}]}', 1, '本人本科阶段在欧洲某理工大学接受全英文数学授课（附英文成绩单），实际英文数学表达流利，申请国际生办豁免 IELTS 0.5 分差额特批。', 'PENDING', NULL, NULL, '');
